--- a/build/reuse_shadow.go
+++ b/build/reuse_shadow.go
@@ -110,8 +110,31 @@ func reuseReceiptPath(root string) (string, error) {
 	return filepath.Join(common, reuseReceiptFile), nil
 }

-// readReuseReceipts reads the receipt file; a missing file holds no receipt, an unreadable or
-// corrupt one is an error.
+// decodeReuseReceipt decodes one receipt line. A complete receipt has every field of reuseReceipt
+// present (status and wall_ms may be zero) and a nonempty key, name, source and log.
+func decodeReuseReceipt(line []byte) (reuseReceipt, bool) {
+	var f struct {
+		Key    *string `json:"key"`
+		Name   *string `json:"name"`
+		Status *int    `json:"status"`
+		WallMS *int64  `json:"wall_ms"`
+		Source *string `json:"source"`
+		Log    *string `json:"log"`
+	}
+	if err := json.Unmarshal(line, &f); err != nil {
+		return reuseReceipt{}, false
+	}
+	if f.Key == nil || f.Name == nil || f.Status == nil || f.WallMS == nil || f.Source == nil || f.Log == nil {
+		return reuseReceipt{}, false
+	}
+	if *f.Key == "" || *f.Name == "" || *f.Source == "" || *f.Log == "" {
+		return reuseReceipt{}, false
+	}
+	return reuseReceipt{Key: *f.Key, Name: *f.Name, Status: *f.Status, WallMS: *f.WallMS, Source: *f.Source, Log: *f.Log}, true
+}
+
+// readReuseReceipts reads the receipt file; a missing file holds no receipt, an unreadable one or
+// one with an incomplete or malformed line is an error.
 func readReuseReceipts(path string) ([]reuseReceipt, error) {
 	raw, err := os.ReadFile(path)
 	if os.IsNotExist(err) {
@@ -125,8 +148,8 @@ func readReuseReceipts(path string) ([]reuseReceipt, error) {
 		if len(bytes.TrimSpace(line)) == 0 {
 			continue
 		}
-		var r reuseReceipt
-		if err := json.Unmarshal(line, &r); err != nil || r.Key == "" {
+		r, ok := decodeReuseReceipt(line)
+		if !ok {
 			return nil, fmt.Errorf("receipt file %s is corrupt at line %d", path, n+1)
 		}
 		out = append(out, r)

