+	if err := appendReuseReceipts(path, reuseReceipt{Key: "x1", Name: "a", Source: reuseSourceBase, Log: "log"}, reuseReceipt{Key: "x2", Name: "a", Source: reuseSourceBase, Log: "log"}); err != nil {
 		t.Fatal(err)
 	}
 	got, _ = readReuseReceipts(path)
@@ -181,3 +181,30 @@ func TestReuseReceiptFileIsBounded(t *testing.T) {
 		t.Fatalf("after a two-receipt append: %d receipts ending %v", len(got), got[len(got)-2:])
 	}
 }
+
+// A receipt line that is valid JSON with a key but lacks another required field is corrupt.
+func TestReadReuseReceiptsRejectsIncompleteRecords(t *testing.T) {
+	complete := `{"key":"k","name":"a","status":0,"wall_ms":0,"source":"baseline","log":"log"}`
+	for name, line := range map[string]string{
+		"key and status only": `{"key":"k","status":0}`,
+		"no name":             `{"key":"k","status":0,"wall_ms":1,"source":"baseline","log":"log"}`,
+		"no wall_ms":          `{"key":"k","name":"a","status":0,"source":"baseline","log":"log"}`,
+		"no source":           `{"key":"k","name":"a","status":0,"wall_ms":1,"log":"log"}`,
+		"no log":              `{"key":"k","name":"a","status":0,"wall_ms":1,"source":"baseline"}`,
+	} {
+		path := filepath.Join(t.TempDir(), reuseReceiptFile)
+		if err := os.WriteFile(path, []byte(complete+"\n"+line+"\n"), 0o600); err != nil {
+			t.Fatal(err)
+		}
+		if _, err := readReuseReceipts(path); err == nil || !strings.Contains(err.Error(), "is corrupt at line 2") {
+			t.Fatalf("%s: error %v, want the corrupt-line error for line 2", name, err)
+		}
+	}
+	path := filepath.Join(t.TempDir(), reuseReceiptFile)
+	if err := os.WriteFile(path, []byte(complete+"\n"), 0o600); err != nil {
+		t.Fatal(err)
+	}
+	if got, err := readReuseReceipts(path); err != nil || len(got) != 1 || got[0].Key != "k" {
+		t.Fatalf("complete receipt: %v, %v", got, err)
+	}
+}

